        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            todo = [(r, c)]
            seen.add((r, c))
            cells = set()
            while todo:
                y, x = todo.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        todo.append(p)
            components.append((color, cells))

    def normalized(cells):
        r0 = min(r for r, c in cells)
        c0 = min(c for r, c in cells)
        return frozenset((r-r0, c-c0) for r, c in cells)

    def tile_hole(hole, available):
        memo = {}
        def rec(uncovered, avail):
            if not uncovered:
                return {}, avail
            key = (frozenset(uncovered), tuple(avail))
            if key in memo:
                return memo[key]
            target = min(uncovered)
            answer = None
            for pos, idx in enumerate(avail):
                color, cells = components[idx]
                for ar, ac in cells:
                    dr, dc = target[0]-ar, target[1]-ac
                    placed = {(r+dr, c+dc) for r, c in cells}
                    if placed <= uncovered:
                        new_avail = avail[:pos] + avail[pos+1:]
                        fills, left = rec(uncovered-placed, new_avail)
                        if fills is not None:
                            answer = ({p: color for p in placed} | fills, left)
                            break
                if answer:
                    break
            memo[key] = answer if answer else (None, None)
            return memo[key]
        return rec(set(hole), list(available))

    for main_index, (color, cells) in enumerate(components):
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        missing = {(r, c) for r in range(r0, r1+1) for c in range(c0, c1+1)} - cells
        if not missing:
            continue
        holes = []
        while missing:
            seed = missing.pop()
            hole = {seed}
            todo = [seed]
            while todo:
                r, c = todo.pop()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (r+dr, c+dc)
                    if p in missing:
                        missing.remove(p)
                        hole.add(p)
                        todo.append(p)
            holes.append(hole)
        available = [i for i in range(len(components)) if i != main_index]
        all_fills = {}
        success = True
        for hole in holes:
            fills, available = tile_hole(hole, available)
            if fills is None:
                success = False
                break
            all_fills.update(fills)
        if success:
            out = [[bg for _ in range(c0, c1+1)] for _ in range(r0, r1+1)]
            for r, c in cells:
                out[r-r0][c-c0] = color
            for (r, c), co in all_fills.items():
                out[r-r0][c-c0] = co
            return out
    return grid
